class Solution {
  public int maxActiveSectionsAfterTrade(String s) {
    int ones = 0, best = 0, prevZeros = 0;
    boolean sawOnesBetween = false;
    int i = 0, n = s.length();
    while (i < n) {
      int j = i;
      while (j < n && s.charAt(j) == s.charAt(i)) j++;
      if (s.charAt(i) == '1') {
        ones += j - i;
        if (prevZeros > 0) sawOnesBetween = true;
      } else {
        int len = j - i;
        // trade: a block of ones between two zero blocks becomes zeros, then the merged zeros turn
        // to ones
        if (prevZeros > 0 && sawOnesBetween) best = Math.max(best, prevZeros + len);
        prevZeros = len;
        sawOnesBetween = false;
      }
      i = j;
    }
    return ones + best;
  }
}
